/// 🛡️ Fallible authored mapping: the received owner is validated by reference under the original control and then retired through funded closure, whether the mapping succeeds or is refused.
pub trait NativeReceiveTryMap<T>:RetireOwned+Sized{fn try_from_native(value:&T,control:&mut NativeDecodeControl<'_>)->Result<Self,ValueError>;}
struct Keep<T>(T);
impl<T:RetireOwned> RetireOwned for Keep<T>{type RetirementCursor=T::RetirementCursor;fn controlled_retirement_supported()->bool{T::controlled_retirement_supported()}fn retirement_seed(self)->Self::RetirementCursor{self.0.retirement_seed()}}
