impl<I:'static+?Sized,T:NativeReceive<I>> NativeReceive<I> for Keep<T>{type Receiver=NativeMappedReceiver<I,T,Keep<T>>;fn receiver()->Self::Receiver{NativeMappedReceiver::new()}}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g}}
