 fn take<'reply>(&mut self,output:&mut Option<U>,effect:&mut semio_framework_value_native_owned::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{if !self.output_ready(){return Ok(reply.complete(Err(invalid().into())))}native_record_pure_take(native_output_take(&mut self.output,output,0,effect),reply)}
